import React, { useState } from 'react';
import Header from './components/Header';
import Footer from './components/Footer';
import Home from './components/Home';
import Productos from './components/Productos';
import Carrito from './components/Carrito';
import Login from './components/Login';
import Contacto from './components/Contacto';
import Registro from './components/Registro';

function App() {
  const [paginaActual, setPaginaActual] = useState('home');
  const [carrito, setCarrito] = useState([]);
  const [usuario, setUsuario] = useState(null);

  const agregarAlCarrito = (producto) => {
    const existe = carrito.find(item => item.id === producto.id);
    if (existe) {
      setCarrito(carrito.map(item => 
        item.id === producto.id 
          ? { ...item, cantidad: item.cantidad + 1 } 
          : item
      ));
    } else {
      setCarrito([...carrito, { ...producto, cantidad: 1 }]);
    }
  };

  const eliminarDelCarrito = (id) => {
    setCarrito(carrito.filter(item => item.id !== id));
  };

  const actualizarCantidad = (id, nuevaCantidad) => {
    if (nuevaCantidad <= 0) {
      eliminarDelCarrito(id);
      return;
    }
    setCarrito(carrito.map(item => 
      item.id === id 
        ? { ...item, cantidad: nuevaCantidad } 
        : item
    ));
  };

  const calcularTotal = () => {
    return carrito.reduce((total, item) => 
      total + (item.precio * item.cantidad), 0
    );
  };

  const navegar = (pagina) => {
    setPaginaActual(pagina);
    window.scrollTo(0, 0);
  };

  const iniciarSesion = (datos) => {
    setUsuario(datos);
    localStorage.setItem('usuario', JSON.stringify(datos));
  };

  const cerrarSesion = () => {
    setUsuario(null);
    localStorage.removeItem('usuario');
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header 
        paginaActual={paginaActual} 
        navegar={navegar} 
        carrito={carrito} 
        usuario={usuario} 
        cerrarSesion={cerrarSesion} 
      />
      <main style={{ flex: 1 }}>
        {paginaActual === 'home' && <Home navegar={navegar} />}
        {paginaActual === 'productos' && <Productos navegar={navegar} agregarAlCarrito={agregarAlCarrito} />}
        {paginaActual === 'carrito' && (
          <Carrito 
            carrito={carrito} 
            eliminarDelCarrito={eliminarDelCarrito} 
            actualizarCantidad={actualizarCantidad} 
            total={calcularTotal()} 
            navegar={navegar} 
          />
        )}
        {paginaActual === 'login' && <Login iniciarSesion={iniciarSesion} navegar={navegar} />}
        {paginaActual === 'registro' && <Registro navegar={navegar} />}
        {paginaActual === 'contacto' && <Contacto navegar={navegar} />}
      </main>
      <Footer navegar={navegar} />
    </div>
  );
}

export default App;
